/// Returns the `n`th Fibonacci number, where `fibonacci(0) == 0` and
/// `fibonacci(1) == 1`.
///
/// Computed iteratively, so this runs in O(n) time and O(1) space.
///
/// # Panics
///
/// Panics on overflow in debug builds once the result exceeds `u64::MAX`
/// (i.e. `n >= 94`).
pub fn fibonacci(n: u64) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_add() {
        assert_eq!(add(2, 3), 5);
    }

    #[test]
    fn test_fibonacci() {
        assert_eq!(fibonacci(0), 0);
        assert_eq!(fibonacci(1), 1);
        assert_eq!(fibonacci(2), 1);
        assert_eq!(fibonacci(10), 55);
        assert_eq!(fibonacci(20), 6765);
    }
}"}
```

